INSERT INTO `cultivation_template` (`template_id`, `template_code`, `template_name`, `variety_name`, `region`, `version`, `template_content`, `template_status`, `created_by`, `created_at`, `updated_at`) VALUES (1,'FJ_NAV_GENERIC','奉节脐橙成年结果树通用管理模板','奉节脐橙','重庆市奉节县',1,'{\"crop\": \"脐橙\", \"region\": \"重庆市奉节县\", \"stages\": [{\"code\": \"SPRING_GROWTH\", \"name\": \"萌芽与春季管理期\", \"tasks\": [{\"name\": \"春季整形修剪\", \"type\": \"PRUNING\", \"offsetDays\": 7}, {\"name\": \"春梢生长巡查\", \"type\": \"PATROL\", \"offsetDays\": 3, \"repeatDays\": 14, \"repeatUntilStageEnd\": true}], \"endMonth\": 3, \"startMonth\": 2, \"managementFocus\": [\"春梢管理\", \"整形修剪\"]}, {\"code\": \"FLOWERING_FRUIT_SET\", \"name\": \"开花坐果期\", \"tasks\": [{\"name\": \"花期与坐果巡查\", \"type\": \"PATROL\", \"offsetDays\": 2, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}], \"endMonth\": 5, \"startMonth\": 4, \"managementFocus\": [\"保花保果\"]}, {\"code\": \"YOUNG_FRUIT\", \"name\": \"幼果与夏季管理期\", \"tasks\": [{\"name\": \"幼果期病虫害检查\", \"type\": \"PEST_CONTROL\", \"offsetDays\": 3, \"repeatDays\": 10, \"repeatUntilStageEnd\": true}], \"endMonth\": 6, \"startMonth\": 6, \"managementFocus\": [\"病虫害防控\"]}, {\"code\": \"FRUIT_EXPANSION\", \"name\": \"果实膨大与秋梢期\", \"tasks\": [{\"name\": \"果实膨大期墒情检查\", \"type\": \"MOISTURE_CHECK\", \"offsetDays\": 0, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"夏季施肥检查\", \"type\": \"FERTILIZATION\", \"offsetDays\": 10}], \"endMonth\": 9, \"startMonth\": 7, \"managementFocus\": [\"墒情管理\", \"秋梢管理\"], \"agronomicMoistureTarget\": {\"max\": 80, \"min\": 70, \"basis\": \"FIELD_CAPACITY_RATIO\", \"irrigateBelow\": 50}}, {\"code\": \"MATURITY\", \"name\": \"转色成熟期\", \"tasks\": [{\"name\": \"果实成熟度抽查\", \"type\": \"PATROL\", \"offsetDays\": 3, \"repeatDays\": 10, \"repeatUntilStageEnd\": true}], \"endMonth\": 11, \"startMonth\": 10, \"managementFocus\": [\"控水提质\", \"成熟度检查\"], \"agronomicMoistureTarget\": {\"max\": 40, \"min\": 30, \"basis\": \"FIELD_CAPACITY_RATIO\"}}, {\"code\": \"HARVEST_POSTHARVEST\", \"name\": \"采收及采后管理期\", \"tasks\": [{\"name\": \"采收准备检查\", \"type\": \"HARVEST\", \"offsetDays\": 7}, {\"name\": \"采后清园巡查\", \"type\": \"ORCHARD_CLEANUP\", \"offsetDays\": 20, \"repeatDays\": 30, \"repeatUntilStageEnd\": true}], \"endMonth\": 2, \"startMonth\": 11, \"managementFocus\": [\"分批采收\", \"采后清园\"]}], \"treeClass\": \"BEARING_TREE\"}','ACTIVE',3,'2026-08-30 03:23:17.676842','2026-08-30 05:25:19.065238'),(2,'FJ_NAV_91','奉园91脐橙成年结果树全周期管理模板','奉园91脐橙','重庆市奉节县',1,'{\"crop\": \"脐橙\", \"region\": \"重庆市奉节县\", \"stages\": [{\"end\": {\"month\": 3, \"period\": \"LATE\"}, \"code\": \"SPRING_GROWTH\", \"name\": \"萌芽与春季管理期\", \"start\": {\"month\": 2, \"period\": \"EARLY\"}, \"tasks\": [{\"name\": \"春季萌芽与树势巡查\", \"type\": \"PATROL\", \"offsetDays\": 0, \"repeatDays\": 14, \"repeatUntilStageEnd\": true}, {\"name\": \"春季土壤墒情检查\", \"type\": \"IRRIGATION_CHECK\", \"offsetDays\": 3, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"春季施肥检查\", \"type\": \"FERTILIZATION\", \"offsetDays\": 7}, {\"name\": \"春季修剪检查\", \"type\": \"PRUNING\", \"offsetDays\": 14}], \"priority\": 50, \"canOverlap\": false, \"managementFocus\": [\"春季施肥\", \"萌芽检查\", \"春季修剪\", \"病虫害巡查\", \"墒情检查\"], \"soilMoistureReference\": {\"note\": \"未检索到奉节本地针对该阶段的独立精确目标区间，前端应显示为定性参考，不与设备实测湿度百分比直接等同。\", \"type\": \"QUALITATIVE\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"referenceText\": \"保持适宜墒情；春梢萌动期应及时灌溉，避免持续干旱或明显积水\", \"irrigationTriggerReference\": {\"unit\": \"%\", \"below\": 60, \"meaning\": \"土壤田间持水量低于约60%时应及时灌水（柑橘通用参考）\"}}}, {\"end\": {\"month\": 5, \"period\": \"LATE\"}, \"code\": \"FLOWERING_FRUIT_SET\", \"name\": \"开花坐果期\", \"start\": {\"month\": 4, \"period\": \"EARLY\"}, \"tasks\": [{\"name\": \"花果状态巡查\", \"type\": \"PATROL\", \"offsetDays\": 0, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"落花落果情况检查\", \"type\": \"PATROL\", \"offsetDays\": 7, \"repeatDays\": 14, \"repeatUntilStageEnd\": true}, {\"name\": \"病虫害巡查\", \"type\": \"PATROL\", \"offsetDays\": 7, \"repeatDays\": 14, \"repeatUntilStageEnd\": true}], \"priority\": 60, \"canOverlap\": false, \"managementFocus\": [\"花果状态观察\", \"保花保果\", \"春梢管理\", \"病虫害巡查\", \"墒情稳定\"], \"soilMoistureReference\": {\"note\": \"未检索到奉节本地花期专属精确目标区间，因此不人为填入min/max。\", \"type\": \"QUALITATIVE\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"referenceText\": \"保持稳定、适宜的土壤水分；开花期属于柑橘需要及时灌溉的关键时期，避免干旱和涝害\", \"irrigationTriggerReference\": {\"unit\": \"%\", \"below\": 60, \"meaning\": \"土壤田间持水量低于约60%时应及时灌水（柑橘通用参考）\"}}}, {\"end\": {\"month\": 6, \"period\": \"LATE\"}, \"code\": \"YOUNG_FRUIT\", \"name\": \"幼果与夏季管理期\", \"start\": {\"month\": 6, \"period\": \"EARLY\"}, \"tasks\": [{\"name\": \"幼果生长状态检查\", \"type\": \"PATROL\", \"offsetDays\": 0, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"夏梢生长检查\", \"type\": \"PRUNING\", \"offsetDays\": 5, \"repeatDays\": 14, \"repeatUntilStageEnd\": true}, {\"name\": \"夏季施肥检查\", \"type\": \"FERTILIZATION\", \"offsetDays\": 10}], \"priority\": 70, \"canOverlap\": false, \"managementFocus\": [\"幼果观察\", \"第二次生理落果管理\", \"夏梢管理\", \"夏季施肥\"], \"soilMoistureReference\": {\"note\": \"未检索到奉节本地幼果期独立精确目标区间，因此保留定性参考。\", \"type\": \"QUALITATIVE\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"referenceText\": \"保持适宜、均衡供水，避免持续干旱；灌水应结合天气、土壤墒情和树势判断\", \"irrigationTriggerReference\": {\"unit\": \"%\", \"below\": 60, \"meaning\": \"土壤田间持水量低于约60%时应及时灌水（柑橘通用参考）\"}}}, {\"end\": {\"month\": 9, \"period\": \"LATE\"}, \"code\": \"FRUIT_EXPANSION\", \"name\": \"果实膨大与秋梢期\", \"start\": {\"month\": 7, \"period\": \"EARLY\"}, \"tasks\": [{\"name\": \"果实膨大期墒情检查\", \"type\": \"IRRIGATION_CHECK\", \"offsetDays\": 0, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"果实膨大情况巡查\", \"type\": \"PATROL\", \"offsetDays\": 7, \"repeatDays\": 14, \"repeatUntilStageEnd\": true}, {\"name\": \"秋梢生长检查\", \"type\": \"PRUNING\", \"offsetDays\": 14, \"repeatDays\": 14, \"repeatUntilStageEnd\": true}], \"priority\": 80, \"canOverlap\": false, \"managementFocus\": [\"稳定水分\", \"果实膨大观察\", \"秋梢管理\", \"病虫害监测\", \"高温干旱防范\"], \"soilMoistureReference\": {\"max\": 80, \"min\": 70, \"note\": \"农业参考口径为田间最大持水量比例，不与设备传感器原始湿度百分比直接等同。\", \"type\": \"QUANTITATIVE\", \"unit\": \"%\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"irrigateBelow\": 50, \"referenceText\": \"果实膨大期土壤持水量宜达到田间最大持水量的70%～80%，低于50%时应及时灌水。\"}, \"agronomicMoistureTarget\": {\"max\": 80, \"min\": 70, \"basis\": \"FIELD_CAPACITY_RATIO\", \"irrigateBelow\": 50}}, {\"end\": {\"month\": 11, \"period\": \"MID\"}, \"code\": \"MATURITY\", \"name\": \"转色成熟期\", \"start\": {\"month\": 10, \"period\": \"EARLY\"}, \"tasks\": [{\"name\": \"果实转色与成熟度巡查\", \"type\": \"PATROL\", \"offsetDays\": 0, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"成熟期墒情检查\", \"type\": \"IRRIGATION_CHECK\", \"offsetDays\": 7, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"采收准备检查\", \"type\": \"HARVEST_PREP\", \"offsetDays\": 14}], \"priority\": 90, \"canOverlap\": false, \"managementFocus\": [\"转色观察\", \"品质管理\", \"成熟期适度控水\", \"采收准备\"], \"soilMoistureReference\": {\"max\": 40, \"min\": 30, \"note\": \"该值为柑橘成熟期专业技术参考，不代表设备传感器原始湿度目标值。\", \"type\": \"QUANTITATIVE\", \"unit\": \"%\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"referenceText\": \"果实成熟期土壤持水量可参考保持在田间最大持水量的30%～40%，采前约1个月适度控水；出现轻微卷叶等缺水表现时应及时补水。\"}, \"agronomicMoistureTarget\": {\"max\": 40, \"min\": 30, \"basis\": \"FIELD_CAPACITY_RATIO\"}}, {\"end\": {\"month\": 1, \"period\": \"LATE\"}, \"code\": \"HARVEST_POSTHARVEST\", \"name\": \"采收与采后管理期\", \"start\": {\"month\": 11, \"period\": \"LATE\"}, \"tasks\": [{\"name\": \"采收条件检查\", \"type\": \"HARVEST_PREP\", \"offsetDays\": 0, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"采后清园\", \"type\": \"CLEANUP\", \"trigger\": \"HARVEST_COMPLETED\", \"offsetDays\": 14}, {\"name\": \"采后果园与设备巡检\", \"type\": \"PATROL\", \"trigger\": \"HARVEST_COMPLETED\", \"offsetDays\": 21}], \"priority\": 100, \"canOverlap\": false, \"managementFocus\": [\"成熟度确认\", \"采收\", \"采后清园\", \"树势恢复\", \"设施巡检\"], \"soilMoistureReference\": {\"note\": \"采后补水属于事件触发型管理要求，不宜给整个阶段设固定min/max。\", \"type\": \"QUALITATIVE\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"referenceText\": \"采收期避免过量供水；采收完成后应及时补水、浇透，使树体恢复正常状态，同时防止积水。\"}}], \"variety\": \"奉园91脐橙\", \"treeClass\": \"BEARING_TREE\", \"maturityClass\": \"EARLY\", \"periodDefinition\": {\"MID\": \"中旬\", \"LATE\": \"下旬\", \"EARLY\": \"上旬\"}, \"stageModelVersion\": \"V1.1\", \"moistureReferencePolicy\": {\"sourceScope\": \"果实膨大期和成熟期采用柑橘专业资料中的定量区间；其他阶段因缺少奉节本地独立精确区间，采用定性参考并保留通用灌水触发参考。\", \"statusJudgement\": \"设备低湿/正常状态继续以threshold_config及传感器标定口径判断；soilMoistureReference用于农业参考、灌溉解释和AI上下文。\", \"sensorMoistureVsFieldCapacity\": \"设备传感器湿度百分比与田间最大持水量比例不是同一口径，不直接比较。\"}, \"moistureReferenceVersion\": \"V1\"}','ACTIVE',3,'2026-08-30 09:29:20.000000','2026-08-31 08:51:03.004700'),(3,'FJ_NAV_72_1','奉园72-1脐橙成年结果树全周期管理模板','奉园72-1脐橙','重庆市奉节县',1,'{\"crop\": \"脐橙\", \"region\": \"重庆市奉节县\", \"stages\": [{\"end\": {\"month\": 3, \"period\": \"LATE\"}, \"code\": \"SPRING_GROWTH\", \"name\": \"萌芽与春季管理期\", \"start\": {\"month\": 2, \"period\": \"EARLY\"}, \"tasks\": [{\"name\": \"春季萌芽与树势巡查\", \"type\": \"PATROL\", \"offsetDays\": 0, \"repeatDays\": 14, \"repeatUntilStageEnd\": true}, {\"name\": \"春季土壤墒情检查\", \"type\": \"IRRIGATION_CHECK\", \"offsetDays\": 3, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"春季施肥检查\", \"type\": \"FERTILIZATION\", \"offsetDays\": 7}, {\"name\": \"春季修剪检查\", \"type\": \"PRUNING\", \"offsetDays\": 14}], \"priority\": 50, \"canOverlap\": false, \"managementFocus\": [\"春季施肥\", \"萌芽检查\", \"春季修剪\", \"病虫害巡查\", \"墒情检查\"], \"soilMoistureReference\": {\"note\": \"未检索到奉节本地针对该阶段的独立精确目标区间，前端应显示为定性参考，不与设备实测湿度百分比直接等同。\", \"type\": \"QUALITATIVE\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"referenceText\": \"保持适宜墒情；春梢萌动期应及时灌溉，避免持续干旱或明显积水\", \"irrigationTriggerReference\": {\"unit\": \"%\", \"below\": 60, \"meaning\": \"土壤田间持水量低于约60%时应及时灌水（柑橘通用参考）\"}}}, {\"end\": {\"month\": 5, \"period\": \"LATE\"}, \"code\": \"FLOWERING_FRUIT_SET\", \"name\": \"开花