rity\": 90, \"canOverlap\": true, \"managementFocus\": [\"特晚熟果转色观察\", \"挂树品质管理\", \"成熟期水分管理\", \"采收准备\"], \"soilMoistureReference\": {\"max\": 40, \"min\": 30, \"note\": \"该值为柑橘成熟期专业技术参考，不代表设备传感器原始湿度目标值。\", \"type\": \"QUANTITATIVE\", \"unit\": \"%\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"referenceText\": \"果实成熟期土壤持水量可参考保持在田间最大持水量的30%～40%，采前约1个月适度控水；出现轻微卷叶等缺水表现时应及时补水。\"}, \"agronomicMoistureTarget\": {\"max\": 40, \"min\": 30, \"basis\": \"FIELD_CAPACITY_RATIO\"}}, {\"end\": {\"month\": 5, \"period\": \"EARLY\"}, \"code\": \"HARVEST_POSTHARVEST\", \"name\": \"采收与采后管理期\", \"start\": {\"month\": 3, \"period\": \"LATE\"}, \"tasks\": [{\"name\": \"红翠2号采收条件检查\", \"type\": \"HARVEST_PREP\", \"offsetDays\": 0, \"repeatDays\": 7, \"repeatUntilStageEnd\": true}, {\"name\": \"采后清园\", \"type\": \"CLEANUP\", \"trigger\": \"HARVEST_COMPLETED\", \"offsetDays\": 14}, {\"name\": \"采后果园与设备巡检\", \"type\": \"PATROL\", \"trigger\": \"HARVEST_COMPLETED\", \"offsetDays\": 21}], \"priority\": 100, \"canOverlap\": true, \"managementFocus\": [\"成熟度确认\", \"特晚熟果采收\", \"采后清园\", \"树势恢复\", \"设施巡检\"], \"soilMoistureReference\": {\"note\": \"采后补水属于事件触发型管理要求，不宜给整个阶段设固定min/max。\", \"type\": \"QUALITATIVE\", \"basis\": \"FIELD_CAPACITY_RATIO\", \"referenceText\": \"采收期避免过量供水；采收完成后应及时补水、浇透，使树体恢复正常状态，同时防止积水。\"}}], \"variety\": \"红翠2号\", \"treeClass\": \"BEARING_TREE\", \"maturityClass\": \"VERY_LATE\", \"periodDefinition\": {\"MID\": \"中旬\", \"LATE\": \"下旬\", \"EARLY\": \"上旬\"}, \"stageModelVersion\": \"V1.1\", \"moistureReferencePolicy\": {\"sourceScope\": \"果实膨大期和成熟期采用柑橘专业资料中的定量区间；其他阶段因缺少奉节本地独立精确区间，采用定性参考并保留通用灌水触发参考。\", \"statusJudgement\": \"设备低湿/正常状态继续以threshold_config及传感器标定口径判断；soilMoistureReference用于农业参考、灌溉解释和AI上下文。\", \"sensorMoistureVsFieldCapacity\": \"设备传感器湿度百分比与田间最大持水量比例不是同一口径，不直接比较。\"}, \"moistureReferenceVersion\": \"V1\"}','ACTIVE',3,'2026-08-30 09:31:23.000000','2026-08-31 08:51:03.004700');
